  5853  /* Serialized data {{{1 */
  5854  static GVariant *
  5855  g_variant_deep_copy (GVariant *value,
  5856                       gboolean  byteswap)
  5857  {
  5858    switch (g_variant_classify (value))
  5859      {
  5860      case G_VARIANT_CLASS_MAYBE:
  5861      case G_VARIANT_CLASS_TUPLE:
  5862      case G_VARIANT_CLASS_DICT_ENTRY:
  5863      case G_VARIANT_CLASS_VARIANT:
  5864        {
  5865          GVariantBuilder builder;
  5866          gsize i, n_children;
  5867
  5868          g_variant_builder_init (&builder, g_variant_get_type (value));
  5869
  5870          for (i = 0, n_children = g_variant_n_children (value); i < n_children; i++)
  5871            {
  5872              GVariant *child = g_variant_get_child_value (value, i);
  5873              g_variant_builder_add_value (&builder, g_variant_deep_copy (child, byteswap));
  5874              g_variant_unref (child);
  5875            }
  5876
  5877          return g_variant_builder_end (&builder);
  5878        }
  5879
  5880      case G_VARIANT_CLASS_ARRAY:
  5881        {
  5882          GVariantBuilder builder;
  5883          gsize i, n_children;
  5884          GVariant *first_invalid_child_deep_copy = NULL;
  5885
  5886          /* Arrays are in theory treated the same as maybes, tuples, dict entries
  5887           * and variants, and could be another case in the above block of code.
  5888           *
  5889           * However, they have the property that when dealing with non-normal
  5890           * data (which is the only time g_variant_deep_copy() is currently
  5891           * called) in a variable-sized array, the code above can easily end up
  5892           * creating many default child values in order to return an array which
  5893           * is of the right length and type, but without containing non-normal
  5894           * data. This can happen if the offset table for the array is malformed.
  5895           *
  5896           * In this case, the code above would end up allocating the same default
  5897           * value for each one of the child indexes beyond the first malformed
  5898           * entry in the offset table. This can end up being a lot of identical
  5899           * allocations of default values, particularly if the non-normal array
  5900           * is crafted maliciously.
  5901           *
  5902           * Avoid that problem by returning a new reference to the same default
  5903           * value for every child after the first invalid one. This results in
  5904           * returning an equivalent array, in normal form and trusted — but with
  5905           * significantly fewer memory allocations.
  5906           *
  5907           * See https://gitlab.gnome.org/GNOME/glib/-/issues/2540 */
  5908
  5909          g_variant_builder_init (&builder, g_variant_get_type (value));
  5910
  5911          for (i = 0, n_children = g_variant_n_children (value); i < n_children; i++)
  5912            {
  5913              /* Try maybe_get_child_value() first; if it returns NULL, this child
  5914               * is non-normal. get_child_value() would have constructed and
  5915               * returned a default value in that case. */
  5916              GVariant *child = g_variant_maybe_get_child_value (value, i);
  5917
  5918              if (child != NULL)
  5919                {
  5920                  /* Non-normal children may not always be contiguous, as they may
  5921                   * be non-normal for reasons other than invalid offset table
  5922                   * entries. As they are all the same type, they will all have
  5923                   * the same default value though, so keep that around. */
  5924                  g_variant_builder_add_value (&builder, g_variant_deep_copy (child, byteswap));
  5925                }
  5926              else if (child == NULL && first_invalid_child_deep_copy != NULL)
  5927                {
  5928                  g_variant_builder_add_value (&builder, first_invalid_child_deep_copy);
  5929                }
  5930              else if (child == NULL)
  5931                {
  5932                  child = g_variant_get_child_value (value, i);
  5933                  first_invalid_child_deep_copy = g_variant_ref_sink (g_variant_deep_copy (child, byteswap));
  5934                  g_variant_builder_add_value (&builder, first_invalid_child_deep_copy);
  5935                }
  5936
  5937              g_clear_pointer (&child, g_variant_unref);
  5938            }
  5939
  5940          g_clear_pointer (&first_invalid_child_deep_copy, g_variant_unref);
  5941
  5942          return g_variant_builder_end (&builder);
  5943        }
  5944
  5945      case G_VARIANT_CLASS_BOOLEAN:
  5946        return g_variant_new_boolean (g_variant_get_boolean (value));
  5947
  5948      case G_VARIANT_CLASS_BYTE:
  5949        return g_variant_new_byte (g_variant_get_byte (value));
  5950
  5951      case G_VARIANT_CLASS_INT16:
  5952        if (byteswap)
  5953          return g_variant_new_int16 (GUINT16_SWAP_LE_BE (g_variant_get_int16 (value)));
  5954        else
  5955          return g_variant_new_int16 (g_variant_get_int16 (value));
  5956
  5957      case G_VARIANT_CLASS_UINT16:
  5958        if (byteswap)
  5959          return g_variant_new_uint16 (GUINT16_SWAP_LE_BE (g_variant_get_uint16 (value)));
  5960        else
  5961          return g_variant_new_uint16 (g_variant_get_uint16 (value));
  5962
  5963      case G_VARIANT_CLASS_INT32:
  5964        if (byteswap)
  5965          return g_variant_new_int32 (GUINT32_SWAP_LE_BE (g_variant_get_int32 (value)));
  5966        else
  5967          return g_variant_new_int32 (g_variant_get_int32 (value));
  5968
  5969      case G_VARIANT_CLASS_UINT32:
  5970        if (byteswap)
  5971          return g_variant_new_uint32 (GUINT32_SWAP_LE_BE (g_variant_get_uint32 (value)));
  5972        else
  5973          return g_variant_new_uint32 (g_variant_get_uint32 (value));
  5974
  5975      case G_VARIANT_CLASS_INT64:
  5976        if (byteswap)
  5977          return g_variant_new_int64 (GUINT64_SWAP_LE_BE (g_variant_get_int64 (value)));
  5978        else
  5979          return g_variant_new_int64 (g_variant_get_int64 (value));
  5980
  5981      case G_VARIANT_CLASS_UINT64:
  5982        if (byteswap)
  5983          return g_variant_new_uint64 (GUINT64_SWAP_LE_BE (g_variant_get_uint64 (value)));
  5984        else
  5985          return g_variant_new_uint64 (g_variant_get_uint64 (value));
  5986
  5987      case G_VARIANT_CLASS_HANDLE:
  5988        if (byteswap)
  5989          return g_variant_new_handle (GUINT32_SWAP_LE_BE (g_variant_get_handle (value)));
  5990        else
  5991          return g_variant_new_handle (g_variant_get_handle (value));
  5992
  5993      case G_VARIANT_CLASS_DOUBLE:
  5994        if (byteswap)
  5995          {
  5996            /* We have to convert the double to a uint64 here using a union,
  5997             * because a cast will round it numerically. */
  5998            union
  5999              {
  6000                guint64 u64;
  6001                gdouble dbl;
  6002              } u1, u2;
  6003            u1.dbl = g_variant_get_double (value);
  6004            u2.u64 = GUINT64_SWAP_LE_BE (u1.u64);
  6005            return g_variant_new_double (u2.dbl);
  6006          }
  6007        else
  6008          return g_variant_new_double (g_variant_get_double (value));
  6009
  6010      case G_VARIANT_CLASS_STRING:
  6011        return g_variant_new_string (g_variant_get_string (value, NULL));
  6012
  6013      case G_VARIANT_CLASS_OBJECT_PATH:
  6014        return g_variant_new_object_path (g_variant_get_string (value, NULL));
  6015
  6016      case G_VARIANT_CLASS_SIGNATURE:
  6017        return g_variant_new_signature (g_variant_get_string (value, NULL));
  6018      }
  6019
  6020    g_assert_not_reached ();
  6021  }
